import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const UpdateOrder = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: ""
  });

  useEffect(() => {
    const fetchOrder = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/orders/${id}`);
        setOrder(res.data || {});
      } catch (err) {
        console.error("Error fetching order:", err);
      }
    };
    fetchOrder();
  }, [id]);

  const handleChange = (e) => {
    setOrder({ ...order, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:5000/orders/${id}`, order);
      alert("Order updated successfully!");
      navigate("/all-orders");
    } catch (error) {
      console.error("Error updating order:", error);
      alert("Failed to update the order. Try again.");
    }
  };

  return (
    <div style={{ maxWidth: "600px", margin: "auto", padding: "20px", backgroundColor: "#f9f9f9", borderRadius: "8px" }}>
      <h2 style={{ textAlign: "center" }}>Update Order</h2>
      <form onSubmit={handleSubmit}>
        {Object.keys(order).map((key) => (
          <div key={key} style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", fontWeight: "bold" }}>{key.replace(/([A-Z])/g, ' $1').trim()}</label>
            <input
              type="text"
              name={key}
              value={order[key] || ""}
              onChange={handleChange}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            />
          </div>
        ))}
        <button type="submit" style={{ backgroundColor: "black", color: "white", padding: "10px 15px", border: "none", borderRadius: "5px", cursor: "pointer", width: "100%" }}>Update Order</button>
      </form>
      <button onClick={() => navigate("/all-orders")} style={{ marginTop: "10px", backgroundColor: "#dc2626", color: "white", padding: "10px 15px", border: "none", borderRadius: "5px", cursor: "pointer", width: "100%" }}>Cancel</button>
    </div>
  );
};

export default UpdateOrder;
